-- Migration: Year 2 - Hematology Pathology MCQs Part 5 (161-200)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- ACUTE LYMPHOBLASTIC LEUKEMIA (161-172)
    (v_topic_id, 'Acute Lymphoblastic Leukemia (ALL) is the most common cancer in children. What is the peak age of incidence?', '["Neonates (0-1 year)", "Children aged 2-5 years", "Teenagers (13-18)", "Adults over 50"]', 1, 'ALL peaks at age 2-5. It accounts for ~80% of childhood leukemias. The incidence declines in adulthood. Adults with ALL have a worse prognosis than children.'),
    (v_topic_id, 'ALL is diagnosed by finding lymphoblasts in the bone marrow. What percentage of marrow blasts is required for diagnosis of acute leukemia?', '["Greater than 5%", "Greater than 10%", "Greater than 20%", "Greater than 50%"]', 2, 'By WHO criteria, acute leukemia is defined as >20% blasts in the bone marrow (or peripheral blood). The exception: AML with specific cytogenetics (e.g., t(15;17), t(8;21)) is diagnosed regardless of blast count.'),
    (v_topic_id, 'Which cytogenetic finding in ALL is associated with the BEST prognosis in children?', '["t(9;22) Philadelphia chromosome", "Hyperdiploidy (>50 chromosomes per cell)", "t(4;11) — MLL rearrangement", "t(1;19)"]', 1, 'Hyperdiploidy (extra chromosomes, especially trisomies of chromosomes 4, 10, 17) is associated with excellent prognosis in childhood ALL (~90% cure rate). The extra chromosomes increase sensitivity to methotrexate and other antimetabolites.'),
    (v_topic_id, 'Which cytogenetic finding in ALL carries the WORST prognosis?', '["Hyperdiploidy", "t(12;21) — ETV6-RUNX1", "Philadelphia chromosome — t(9;22) BCR-ABL (Ph+ ALL)", "Trisomy 21 (Down syndrome)"]', 2, 'Ph+ ALL (BCR-ABL fusion from t(9;22)) is present in ~25% of adult ALL and carries the worst prognosis without targeted therapy. Treatment now includes imatinib/dasatinib added to chemotherapy, dramatically improving outcomes.'),
    (v_topic_id, 'The immunophenotype of B-ALL (precursor B-cell ALL, most common type) is?', '["CD3+, CD7+, TdT+", "CD19+, CD10+, TdT+, CD34+ (positive for TdT distinguishes ALL from mature B-cell lymphomas)", "CD20+, CD5+, CD23+", "CD15+, CD30+"]', 1, 'B-ALL: CD19+ (B-cell), CD10+ (CALLA, common ALL antigen), TdT+ (terminal deoxynucleotidyl transferase — marks immature lymphoid precursors), CD34+ (stem cell marker). TdT positivity is the key marker distinguishing ALL from Burkitt lymphoma/leukemia.'),
    (v_topic_id, 'T-ALL is associated with which clinical presentation that B-ALL rarely causes?', '["Bone pain and anemia", "Anterior mediastinal mass (thymic origin) causing SVC syndrome in adolescent males", "CNS involvement at diagnosis", "Skin infiltration"]', 1, 'T-ALL arises from thymic T-cell precursors. It characteristically presents in adolescent/young adult males with a large anterior mediastinal mass (from thymic involvement). Can compress the SVC, airways, or both. Mediastinal mass in a young male = T-ALL until proven otherwise.'),
    (v_topic_id, 'CNS prophylaxis (intrathecal chemotherapy) is mandatory in ALL treatment. Why?', '["The blood-brain barrier prevents chemotherapy from reaching CNS lymphoblasts, which would cause CNS relapse without targeted intrathecal therapy", "ALL causes brain hemorrhage", "Cranial irradiation causes hearing loss", "CNS is the primary site of ALL"]', 0, 'The BBB is a sanctuary site. Most systemic chemotherapy does not penetrate the CSF adequately. Without intrathecal therapy (methotrexate +/- cytarabine, hydrocortisone), CNS relapse occurs in nearly all patients. Lumbar puncture with intrathecal chemo is part of all ALL protocols.'),
    (v_topic_id, 'The overall cure rate for childhood B-ALL with modern therapy is approximately?', '["20-30%", "50-60%", "Greater than 90%", "40-50%"]', 2, 'Childhood B-ALL has one of the highest cure rates of any cancer: >90% with modern multiagent chemotherapy. This compares to adult ALL (~40-50% cure), illustrating the prognostic importance of biology (hyperdiploidy, favorable fusions) more common in children.'),
    (v_topic_id, 'Down syndrome (Trisomy 21) children have a 20-fold increased risk of ALL. They also have an increased risk of which AML subtype?', '["APL (AML-M3)", "Acute Megakaryoblastic Leukemia (AMKL, AML-M7)", "AML with t(8;21)", "AML-M5 (monocytic)"]', 1, 'Down syndrome is strongly associated with: (1) Transient Myeloproliferative Disorder (TMD) in neonates — resolves spontaneously; (2) AMKL (AML-M7) before age 4 — GATA1 mutation. Paradoxically, Down syndrome ALL has excellent prognosis.'),
    (v_topic_id, 'Lymphoblasts in ALL are PAS (Periodic Acid-Schiff) positive. Which stain is used to identify myeloblasts in AML?', '["PAS stain", "Myeloperoxidase (MPO) stain or Sudan Black B stain", "Oil Red O for lipids", "Prussian blue for iron"]', 1, 'MPO (myeloperoxidase) stains myeloid granules, identifying myeloblasts and promyelocytes in AML. Sudan Black B stains lipids in myeloid granules similarly. Auer rods (crystallized MPO) are pathognomonic of AML. TdT stains ALL blasts; MPO stains AML blasts.'),
    (v_topic_id, 'Auer rods in a leukemic blast are pathognomonic of which disease?', '["Acute Lymphoblastic Leukemia", "Acute Myeloid Leukemia (AML) — Auer rods are crystallized cytoplasmic granules of myeloperoxidase", "CML blast crisis", "CLL"]', 1, 'Auer rods are pink, needle-like crystalline inclusions in the cytoplasm of myeloblasts. They represent fused azurophilic granules containing myeloperoxidase. Their presence in a blast confirms AML (or CML blast crisis). Most characteristic in APL (M3), where they form faggot cells (bundles of Auer rods).'),
    (v_topic_id, 'Faggot cells (blasts with multiple Auer rods bundled like sticks) are pathognomonic of which AML subtype?', '["AML-M1 (minimally differentiated)", "AML-M3 (Acute Promyelocytic Leukemia, APL)", "AML-M5 (monocytic)", "AML-M7 (megakaryoblastic)"]', 1, 'APL (AML-M3): promyelocytes packed with Auer rods forming bundles (faggot cells). The granules contain massive amounts of thromboplastic material (tissue factor), which when released causes life-threatening DIC. APL also has t(15;17) creating PML-RARA fusion.'),

    -- ACUTE MYELOID LEUKEMIA (173-182)
    (v_topic_id, 'APL (AML-M3) has the translocation t(15;17). What does this create?', '["BCR-ABL fusion (constitutive tyrosine kinase)", "PML-RARA fusion: blocks myeloid differentiation at the promyelocyte stage by dominant-negative inhibition of retinoic acid receptor", "NPM-ALK fusion", "ETV6-RUNX1 fusion"]', 1, 'Normal RAR-alpha (retinoic acid receptor) drives myeloid differentiation. PML-RARA fusion blocks this in a dominant-negative manner, freezing maturation at the promyelocyte stage. ATRA (all-trans retinoic acid) overcomes the block by forcing PML-RARA to release transcriptional repressors, allowing differentiation.'),
    (v_topic_id, 'ATRA (all-trans retinoic acid) is used to treat APL. What is its mechanism?', '["It kills promyelocytes by inducing apoptosis", "It pharmacologically overcomes the PML-RARA block, forcing the leukemic promyelocytes to differentiate into mature neutrophils", "It inhibits the BCR-ABL kinase", "It chelates arsenic to prevent toxicity"]', 1, 'ATRA binds the PML-RARA fusion protein with higher affinity than normal retinoic acid, causing it to release its transcriptional repressors and differentiate. Remarkably, the cells differentiate into mature neutrophils and die naturally. ATRA + arsenic trioxide = cure rate >90% for APL.'),
    (v_topic_id, 'Differentiation Syndrome (formerly ATRA syndrome) is a complication of ATRA therapy for APL. What causes it?', '["Bone marrow suppression from ATRA toxicity", "Rapid differentiation of millions of promyelocytes into mature neutrophils, which migrate to lungs and cause pulmonary inflammation and edema", "Systemic histamine release", "Complement activation"]', 1, 'As APL promyelocytes differentiate rapidly, the newly formed mature neutrophils release inflammatory cytokines and infiltrate the lungs and other tissues, causing fever, pulmonary infiltrates, pleural/pericardial effusions, and hypotension. Treatment: dexamethasone (high-dose corticosteroids).'),
    (v_topic_id, 'Which AML subtype is associated with t(8;21), causing AML-ETO fusion?', '["AML-M3 (APL)", "AML-M2 (AML with maturation): characteristic Auer rods, salmon-colored granules, associated with chloromas (granulocytic sarcomas)", "AML-M5 (monocytic)", "AML-M7 (megakaryoblastic)"]', 1, 'AML with t(8;21): RUNX1-RUNX1T1 (AML-ETO) fusion is one of the favorable-risk AML cytogenetics. Morphology: AML-M2 with large blasts containing single Auer rods and salmon-pink granules. Can form chloromas (green-colored extramedullary deposits from myeloperoxidase).'),
    (v_topic_id, 'AML-M4Eo (AML with eosinophilia) is associated with which cytogenetic abnormality?', '["t(8;21)", "inv(16) or t(16;16) — CBFB-MYH11 fusion", "t(15;17)", "11q23 MLL rearrangement"]', 1, 'AML-M4Eo: inv(16) causes CBFB-MYH11 fusion, which disrupts the CBF (core binding factor) transcription complex needed for myeloid differentiation. Associated with abnormal eosinophils with large basophilic granules. Like t(8;21), inv(16) is a favorable-risk AML.'),
    (v_topic_id, 'AML-M5 (monocytic leukemia) most commonly involves which organ sites outside the bone marrow?', '["Lungs and kidneys", "Gums (gingival hyperplasia from monocyte infiltration) and skin (leukemia cutis)", "Brain and testes", "Spleen only"]', 1, 'Monocytic AML (M4/M5) has the highest propensity for extramedullary involvement. Monocytes naturally traffic to tissues. Classic sites: gingival hyperplasia (swollen, bleeding gums from monocyte infiltration), skin (leukemia cutis — violaceous plaques), and CNS.'),
    (v_topic_id, 'Which AML is most common in older adults (de novo in elderly) and has the worst prognosis among common AML subtypes?', '["AML with favorable cytogenetics (t(8;21), inv(16), t(15;17))", "AML with complex karyotype (3+ abnormalities) or monosomy 5/7, common in elderly and after prior chemotherapy exposure", "AML-M3 (APL)", "AML with NPM1 mutation without FLT3"]', 1, 'AML with complex karyotype, monosomy 5, or monosomy 7 is most common in therapy-related AML (t-AML) from prior alkylating agents/radiation and in elderly de novo AML. These are adverse-risk lesions with very poor response to standard chemotherapy.'),
    (v_topic_id, 'NPM1 mutation and FLT3-ITD mutation are two common mutations in AML. Which combination confers the WORST prognosis?', '["NPM1 mutated, FLT3 wild-type", "NPM1 wild-type, FLT3-ITD positive (high allelic ratio)", "NPM1 mutated, FLT3-ITD positive", "Both wild-type"]', 1, 'FLT3-ITD (internal tandem duplication in FLT3 receptor tyrosine kinase) drives uncontrolled proliferation. FLT3-ITD+ without NPM1 mutation = adverse risk. NPM1 mutated without FLT3-ITD = favorable risk (even with normal karyotype). Midostaurin (FLT3 inhibitor) is now added to AML chemotherapy for FLT3-mutated patients.'),
    (v_topic_id, 'Induction chemotherapy for AML is called the 7+3 regimen. What does 7+3 mean?', '["7 drugs for 3 days", "7 days of cytarabine (ara-C) continuous infusion + 3 days of an anthracycline (daunorubicin or idarubicin)", "7 cycles of 3 drugs each", "7 hours of infusion over 3 weeks"]', 1, '7+3: cytarabine (antimetabolite, disrupts DNA synthesis) for 7 days continuously + anthracycline (daunorubicin or idarubicin) for 3 days. Goal: achieve complete remission (CR = <5% blasts in marrow). CR is achieved in ~60-80% of younger patients. Consolidation follows with high-dose cytarabine or allogeneic HSCT.'),

    -- CHRONIC MYELOID LEUKEMIA (183-190)
    (v_topic_id, 'Chronic Myeloid Leukemia (CML) is defined by which translocation?', '["t(14;18) — BCL2", "t(9;22) — Philadelphia chromosome (BCR-ABL1 fusion), creating a constitutively active tyrosine kinase", "t(8;14) — c-MYC", "t(15;17) — PML-RARA"]', 1, 'The Philadelphia chromosome t(9;22) fuses the BCR gene on chromosome 22 to the ABL1 tyrosine kinase gene on chromosome 9. The BCR-ABL fusion protein has constitutive, unregulated kinase activity that drives uncontrolled myeloid proliferation. Present in >95% of CML.'),
    (v_topic_id, 'A 55-year-old man has WBC of 120,000 with a full spectrum of myeloid cells (blasts, promyelocytes, myelocytes, basophils, eosinophils) in peripheral blood. Spleen is massively enlarged. What is the diagnosis?', '["Leukemoid reaction from severe infection", "Chronic Myeloid Leukemia (CML) in chronic phase", "AML", "CLL"]', 1, 'CML classic presentation: marked leukocytosis with ALL stages of myeloid maturation (no maturation block), basophilia, eosinophilia, thrombocytosis, and massive splenomegaly (from extramedullary hematopoiesis). LAP score is LOW (unlike leukemoid reaction). BCR-ABL FISH/RT-PCR confirms.'),
    (v_topic_id, 'Basophilia is an important clue to CML. Why is it clinically relevant?', '["Basophils produce antibodies against RBCs", "Basophils contain histamine; high basophil counts cause histamine release leading to pruritus, peptic ulcers, and diarrhea", "Basophilia indicates accelerated phase immediately", "Basophils cause splenomegaly"]', 1, 'Basophilia is one of the cardinal features of CML (and other myeloproliferative neoplasms). Excess basophil degranulation releases histamine, causing pruritus (aquagenic), peptic ulcers (histamine stimulates gastric acid), flushing, and diarrhea.'),
    (v_topic_id, 'Imatinib (Gleevec) revolutionized CML treatment. What is its mechanism?', '["It inhibits BCL2, promoting apoptosis of CML cells", "It competitively inhibits the BCR-ABL tyrosine kinase ATP-binding site, blocking kinase activity and halting leukemic cell proliferation", "It induces differentiation of CML blasts", "It targets CD20 on CML cells"]', 1, 'Imatinib was the first targeted cancer therapy based on molecular understanding of oncogenesis. It occupies the ATP-binding pocket of BCR-ABL kinase, preventing phosphorylation of downstream survival signals. 10-year overall survival with imatinib: >80-85% for chronic-phase CML (a former fatal disease).'),
    (v_topic_id, 'CML can transform to blast crisis (acute leukemia). Which type of blast crisis is more common?', '["T-lymphoid blast crisis (50%)", "Myeloid blast crisis (70%) or lymphoid blast crisis (30%, often B-cell)", "Mixed myeloid/lymphoid blast crisis (100%)", "All blast crises are myeloid"]', 1, 'CML blast crisis (>20% blasts): ~70% are myeloid (AML-like), ~30% are lymphoid (usually B-ALL-like). Lymphoid blast crisis can respond to ALL-type therapy (vincristine, prednisone, imatinib). Allogeneic HSCT is the only curative option in blast crisis.'),
    (v_topic_id, 'The Sokal score and EUTOS score are used to risk-stratify CML at diagnosis. Which finding worsens prognosis?', '["Low WBC at diagnosis", "Large spleen (>10 cm below costal margin), high blast percentage, thrombocytopenia or extreme thrombocytosis", "Presence of BCR-ABL", "Age under 40"]', 1, 'High-risk features at CML diagnosis: large spleen, high blasts (approaching accelerated phase), extreme thrombocytosis or thrombocytopenia, and high WBC. These patients may need second-generation TKIs (dasatinib, nilotinib) as first-line therapy.'),
    (v_topic_id, 'A patient with CML develops T315I mutation in BCR-ABL on imatinib therapy. Why does this cause resistance?', '["T315I increases BCR-ABL kinase activity 100-fold", "T315I (gatekeeper mutation) changes the amino acid at the ATP-binding site, preventing imatinib from binding while leaving kinase activity intact", "T315I causes BCR-ABL to stop expressing", "T315I activates an alternative kinase pathway"]', 1, 'T315I (threonine to isoleucine at position 315) is the gatekeeper mutation — it prevents imatinib, dasatinib, and nilotinib from binding. Ponatinib (3rd-generation TKI) is the only approved TKI that overcomes T315I. Asciminib (STAMP inhibitor) is an alternative.'),
    (v_topic_id, 'What distinguishes CML from a leukemoid reaction in terms of the leukocyte alkaline phosphatase (LAP) score?', '["CML has high LAP; leukemoid reaction has low LAP", "CML has LOW LAP (neoplastic neutrophils are metabolically abnormal); leukemoid reaction has HIGH LAP (activated normal neutrophils)", "Both have high LAP", "LAP is not useful for this distinction"]', 1, 'LAP (leukocyte alkaline phosphatase) is an enzyme in normal neutrophil granules. In CML, the neoplastic neutrophils produce less LAP (low LAP score <20). In reactive leukocytosis (leukemoid reaction), activated normal neutrophils have high LAP (>100). BCR-ABL PCR is now the gold standard.'),

    -- CHRONIC LYMPHOCYTIC LEUKEMIA (191-200)
    (v_topic_id, 'Chronic Lymphocytic Leukemia (CLL) is the most common adult leukemia. What is its immunophenotype?', '["CD19+, CD5+, CD23+, CD20 (dim), surface Ig (dim) — co-expression of CD5 (T-cell marker) on B-cells is the hallmark", "CD3+, CD4+, CD8-", "CD20+, CD5-, CD23-", "CD19+, CD10+, TdT+"]', 0, 'CLL immunophenotype: CD19+ (B-cell) + CD5+ (T-cell marker aberrantly expressed on neoplastic B-cells) + CD23+ (distinguishes from mantle cell which is CD23-) + dim CD20 + dim surface immunoglobulin. CD5+CD23+ is the diagnostic fingerprint of CLL.'),
    (v_topic_id, 'Smudge cells on peripheral blood smear are pathognomonic of which disease?', '["AML", "CLL (fragile neoplastic B-cells rupture during smear preparation, leaving nuclear chromatin remnants called smudge cells or basket cells)", "ALL", "CML"]', 1, 'CLL lymphocytes are extremely fragile. During peripheral smear preparation (the spreading process), they rupture, leaving nuclear material smears (smudge or basket cells). Smudge cells on a smear = think CLL first.'),
    (v_topic_id, 'Which deletion is the most common cytogenetic abnormality in CLL and carries the BEST prognosis among CLL deletions?', '["del(17p) — loss of TP53", "del(13q) as the sole abnormality — associated with good prognosis and long survival", "del(11q) — loss of ATM", "del(6q)"]', 1, 'del(13q) (loss of miR-15a and miR-16-1, which suppress BCL2) is found in ~55% of CLL and confers the best prognosis when it is the sole abnormality. del(17p) (TP53 loss) is worst, conferring chemo-resistance. del(11q) (ATM loss) is intermediate-poor.'),
    (v_topic_id, 'A patient with CLL develops sudden severe anemia with a positive Direct Coombs test. What is the complication?', '["CLL transforming to AML", "Autoimmune hemolytic anemia (AIHA) — CLL B-cells produce autoantibodies (usually warm IgG) against RBCs", "Pure red cell aplasia from parvovirus", "Iron deficiency from GI bleeding"]', 1, 'CLL commonly causes autoimmune cytopenias: AIHA (most common, warm IgG), immune thrombocytopenic purpura (ITP), and pure red cell aplasia. The neoplastic B-cells produce autoantibodies against blood cell antigens. Treatment: corticosteroids +/- rituximab.'),
    (v_topic_id, 'Richter Transformation in CLL refers to?', '["CLL transforming to CML", "Transformation of CLL to an aggressive lymphoma — most commonly Diffuse Large B-Cell Lymphoma (DLBCL) — presenting with rapid lymph node enlargement, fever, weight loss, and elevated LDH", "CLL becoming AML", "CLL becoming multiple myeloma"]', 1, 'Richter transformation occurs in ~5-10% of CLL patients. The indolent CLL clone acquires additional mutations (often TP53, MYC) and transforms to aggressive DLBCL. Clinical clue: a stable CLL patient suddenly develops rapidly enlarging nodes and B symptoms. Prognosis is very poor.'),
    (v_topic_id, 'The Rai staging system for CLL is based on clinical findings. Which Rai stage has the WORST prognosis?', '["Rai Stage 0 (lymphocytosis only)", "Rai Stage I (lymphocytosis + lymphadenopathy)", "Rai Stage IV (lymphocytosis + thrombocytopenia)", "Rai Stage II (lymphocytosis + splenomegaly/hepatomegaly)"]', 2, 'Rai stages: 0 = lymphocytosis only (best, median survival >10 years); I = + lymphadenopathy; II = + splenomegaly/hepatomegaly; III = + anemia (Hgb <11); IV = + thrombocytopenia (PLT <100K). Stages III-IV = high risk, median survival 1-2 years without treatment.'),
    (v_topic_id, 'A CLL patient has mutated IGHV (immunoglobulin heavy chain variable gene). How does this affect prognosis compared to unmutated IGHV?', '["Mutated IGHV confers worse prognosis because mutations indicate genomic instability", "Mutated IGHV confers BETTER prognosis (median survival >20 years) because it indicates the cell originated from a post-germinal center B-cell that has undergone normal antigen selection", "No difference in prognosis", "Mutated IGHV always requires immediate treatment"]', 1, 'IGHV mutation status is one of the most important prognostic markers in CLL. Mutated IGHV (post-germinal center B-cell origin) = indolent disease, long survival, often does not require treatment. Unmutated IGHV = naive B-cell origin, aggressive disease, earlier need for therapy.'),
    (v_topic_id, 'Venetoclax is a novel targeted therapy for CLL. What is its mechanism?', '["Anti-CD20 monoclonal antibody", "BCL2 inhibitor — BCL2 is overexpressed in CLL (partly due to del(13q) miRNA loss), and venetoclax blocks BCL2 to restore apoptosis", "BTK inhibitor", "PI3K-delta inhibitor"]', 1, 'Venetoclax is a highly selective BCL2 inhibitor. BCL2 overexpression is universal in CLL (driven by t(14;18)-independent mechanisms including loss of miR-15a/16-1 from del(13q)). Blocking BCL2 releases BAX/BAK-mediated apoptosis, killing CLL cells selectively.'),
    (v_topic_id, 'Small Lymphocytic Lymphoma (SLL) and CLL are the same disease. What distinguishes them clinically?', '["SLL has T-cell immunophenotype; CLL has B-cell immunophenotype", "In CLL, the absolute lymphocyte count is >5000/mcL in blood; in SLL, the same neoplastic B-cells involve lymph nodes and spleen but blood count is <5000/mcL", "SLL involves only lymph nodes; CLL involves only bone marrow", "They are completely different diseases with different treatment"]', 1, 'CLL vs. SLL: identical immunophenotype (CD19+, CD5+, CD23+) and pathobiology. CLL = peripheral blood involvement (ALC >5000) + marrow involvement. SLL = nodal/splenic disease without meeting blood criteria. Both are treated the same way with BTK inhibitors (ibrutinib, acalabrutinib) or venetoclax-based regimens.'),
    (v_topic_id, 'Hairy Cell Leukemia is a rare B-cell leukemia. What are its characteristic features on peripheral blood smear and bone marrow?', '["Smudge cells and dry tap on marrow biopsy", "Hairy cells (B-lymphocytes with cytoplasmic projections = hairlike filopods) on smear; dry tap on marrow biopsy (reticulin fibrosis); TRAP (tartrate-resistant acid phosphatase) stain positive", "Auer rods and myeloperoxidase positive blasts", "Plasma cells with Dutcher bodies"]', 1, 'Hairy cell leukemia: TRAP+ (classic stain), CD11c+, CD25+, CD103+, CD123+, Annexin A1+ (most specific). Bone marrow biopsy shows fried-egg appearance of hairy cells with abundant pale cytoplasm and widely spaced nuclei. Dry tap from reticulin fibrosis. BRAF V600E mutation present in virtually all cases.'),
    (v_topic_id, 'The treatment of choice for hairy cell leukemia is?', '["R-CHOP chemotherapy", "Cladribine (2-CdA) or pentostatin — purine analogues that achieve durable complete remission in >80% of patients after a single course", "Imatinib", "ATRA + arsenic trioxide"]', 1, 'Cladribine (2-chlorodeoxyadenosine) is the preferred treatment for HCL. A single 5-7 day course achieves complete remission in >80-90% of patients with durable responses lasting many years. BRAF V600E inhibitors (vemurafenib) are used in relapsed/refractory HCL.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
